function validate([licensePlate, words]) {
  if (typeof licensePlate !== 'string' || licensePlate.length < 1 || licensePlate.length > 7) return 'licensePlate needs 1 to 7 characters.';
  if (!/^[0-9a-zA-Z ]+$/.test(licensePlate)) return 'licensePlate holds only digits, letters and spaces.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 words.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{1,15}$/.test(w))) return 'Each word is 1 to 15 lowercase letters.';
  const need = {};
  for (const c of licensePlate.toLowerCase()) if (c >= 'a' && c <= 'z') need[c] = (need[c] || 0) + 1;
  const completes = w => Object.entries(need).every(([c, k]) => w.split(c).length - 1 >= k);
  if (!words.some(completes)) return 'At least one word must complete licensePlate.';
  return null;
}

