function shortestCompletingWord(licensePlate, words) {
  const letters = [...licensePlate].filter(c => /[a-zA-Z]/.test(c)).map(c => c.toLowerCase());
  const order = words.map((word, index) => ({ word, index })).sort((a, b) => a.word.length - b.word.length || a.index - b.index);
  for (const { word } of order) {
    const left = word.split('');
    let ok = true;
    for (const c of letters) {
      const at = left.indexOf(c);
      if (at < 0) { ok = false; break; }
      left.splice(at, 1);
    }
    if (ok) return word;
  }
  return null;
}

