function generate(rand, size) {
  const large = size === 'large';
  const alphabet = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abcdefghijklmnopqrstuvwxyz'.slice(0, 2 + Math.floor(rand() * 5));
  const pick = s => s[Math.floor(rand() * s.length)];
  const plateLength = 1 + Math.floor(rand() * 7);
  let plate = '';
  for (let i = 0; i < plateLength; i++) {
    const r = rand();
    if (r < 0.2) plate += pick('0123456789');
    else if (r < 0.3) plate += ' ';
    else {
      const c = pick(alphabet);
      plate += rand() < 0.5 ? c.toUpperCase() : c;
    }
  }
  const letters = [...plate.toLowerCase()].filter(c => c >= 'a' && c <= 'z');
  const randomWord = () => {
    const length = 1 + Math.floor(rand() * (large ? 15 : 6));
    let w = '';
    for (let i = 0; i < length; i++) w += pick(alphabet);
    return w;
  };
  const n = large ? 1000 : 1 + Math.floor(rand() * 8);
  const words = Array.from({ length: n }, randomWord);
  // Guarantee an answer: one word holds every plate letter plus a few random ones, in shuffled order.
  const extra = Math.floor(rand() * (Math.min(15, letters.length + 4) - letters.length + 1));
  const chars = [...letters];
  for (let i = 0; i < extra || chars.length === 0; i++) chars.push(pick(alphabet));
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  words[Math.floor(rand() * n)] = chars.join('');
  return [plate, words];
}
